import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERR', d); sys.exit(1)
for c in d['channels']:
    if c['name'] in ('launch-plan','launch_plan'):
        print(c['id'], c['name'], c.get('is_archived'))
"

